export const developersExportToPDF = async (data: any[]) => {
  const { default: jsPDF } = await import("jspdf");
  const doc = new jsPDF({ orientation: "landscape" });

  const title = "Developers Report";
  const generated = `Generated: ${new Date().toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  })}`;

  doc.setFillColor(13, 148, 136); // teal-600
  doc.rect(0, 0, doc.internal.pageSize.width, 18, "F");
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(13);
  doc.setFont("helvetica", "bold");
  doc.text(title, 14, 12);
  doc.setFontSize(8);
  doc.setFont("helvetica", "normal");
  doc.text(generated, doc.internal.pageSize.width - 14, 12, { align: "right" });

  doc.setTextColor(0, 0, 0);

  const cols = [
    { header: "Developer Name", key: "developer_name", width: 55 },
    { header: "Email", key: "email", width: 50 },
    { header: "Phone Number", key: "phone_number", width: 35 },
    { header: "Website", key: "website", width: 45 },
    { header: "Countries", key: "countries", width: 35 },
    { header: "Projects", key: "projects_count", width: 25 },
    { header: "Status", key: "status", width: 25 },
  ];

  let xPos = 14;
  let yPos = 28;
  const rowHeight = 8;
  const pageHeight = doc.internal.pageSize.height;

  doc.setFillColor(243, 244, 246);
  doc.rect(14, yPos - 5, doc.internal.pageSize.width - 28, rowHeight, "F");
  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(55, 65, 81);

  cols.forEach((col) => {
    doc.text(col.header, xPos, yPos);
    xPos += col.width;
  });

  yPos += rowHeight;
  doc.setFont("helvetica", "normal");
  doc.setTextColor(31, 41, 55);

  data.forEach((d: any, rowIndex: number) => {
    if (yPos + rowHeight > pageHeight - 15) {
      doc.addPage();
      yPos = 20;

      doc.setFillColor(243, 244, 246);
      doc.rect(14, yPos - 5, doc.internal.pageSize.width - 28, rowHeight, "F");
      doc.setFont("helvetica", "bold");
      doc.setFontSize(8);
      doc.setTextColor(55, 65, 81);
      let hX = 14;
      cols.forEach((col) => {
        doc.text(col.header, hX, yPos);
        hX += col.width;
      });
      yPos += rowHeight;
      doc.setFont("helvetica", "normal");
      doc.setTextColor(31, 41, 55);
    }

    if (rowIndex % 2 === 1) {
      doc.setFillColor(249, 250, 251);
      doc.rect(14, yPos - 5, doc.internal.pageSize.width - 28, rowHeight, "F");
    }

    xPos = 14;
    cols.forEach((col) => {
      let val = d[col.key] ?? d[col.key.replace("developer_", "")] ?? d.name ?? "—";
      if (col.key === "status") {
        val = d.status === "active" || d.status === true || d.is_active ? "Active" : "Inactive";
      }
      if (typeof val === "object") val = JSON.stringify(val);
      const strVal = String(val);
      const truncated = strVal.length > 26 ? strVal.substring(0, 24) + "…" : strVal;
      doc.text(truncated, xPos, yPos);
      xPos += col.width;
    });

    yPos += rowHeight;
  });

  const pageCount = (doc as any).internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setTextColor(156, 163, 175);
    doc.text(
      `Page ${i} of ${pageCount}`,
      doc.internal.pageSize.width / 2,
      doc.internal.pageSize.height - 6,
      { align: "center" }
    );
  }

  doc.save("Developers_Report.pdf");
};

export const developersExportToCsv = (data: any[]) => {
  if (!data.length) return;

  const columns = [
    "developer_id",
    "developer_name",
    "email",
    "phone_number",
    "website",
    "countries",
    "cities",
    "projects_count",
    "status",
  ];

  const header = [
    "ID",
    "Name",
    "Email",
    "Phone Number",
    "Website",
    "Countries",
    "Cities",
    "Projects Count",
    "Status",
  ].join(",");

  const rows = data.map((d: any) =>
    columns
      .map((col) => {
        let val = d[col] ?? d[col.replace("developer_", "")] ?? "";
        if (col === "status") {
          val = d.status === "active" || d.status === true || d.is_active ? "Active" : "Inactive";
        }
        const str = String(val).replace(/"/g, '""');
        return `"${str}"`;
      })
      .join(",")
  );

  const csvContent = [header, ...rows].join("\n");
  const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "Developers_Report.csv";
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const developersExportToExcel = async (data: any[]) => {
  const XLSX = await import("xlsx");
  const formattedData = data.map((d: any) => ({
    "ID": d.developer_id ?? d.id ?? "N/A",
    "Developer Name": d.developer_name ?? d.name ?? "N/A",
    "Email": d.email ?? "N/A",
    "Phone Number": d.phone_number ?? d.contact ?? "N/A",
    "Website": d.website ?? "N/A",
    "Countries": d.countries ?? "N/A",
    "Cities": d.cities ?? "N/A",
    "Projects Count": d.projects_count ?? d.projects ?? 0,
    "Status": d.status === "active" || d.status === true || d.is_active ? "Active" : "Inactive",
    "Is Top": d.is_top === 1 || d.is_top === true ? "Yes" : "No",
  }));

  const worksheet = XLSX.utils.json_to_sheet(formattedData);
  const workbook = XLSX.utils.book_new();

  const header = Object.keys(formattedData[0] || {});
  const columnWidths = header.map((h) => ({
    wch:
      Math.max(
        h.length,
        ...formattedData.map((row: any) => row[h]?.toString().length || 10),
      ) + 2,
  }));
  worksheet["!cols"] = columnWidths;
  worksheet["!freeze"] = { xSplit: 0, ySplit: 1 };

  XLSX.utils.book_append_sheet(workbook, worksheet, "Developers");
  XLSX.writeFile(workbook, "Developers_Report.xlsx");
};
